import {transform,block,doc,heading,paired,unwrap,retire,clearArrangement,dryRunMain} from './layout-repair-common-20261004.mjs';
import {resolveArrangement} from '../../src/lib/booklet-arrangement.js';
export const PROJECTS=['solve-2-step-equations-v1'];
function rowParts(row,b){const worked={id:row.id,type:'part',label:'',prompt:unwrap(row.prompt,b),answerSpaceMm:0};const children=row.children;for(const c of children)c.prompt=typeof c.prompt==='object'?unwrap(c.prompt,b):c.prompt;return [worked,{id:row.id+'-turn-grid',type:'group',label:'',layout:'grid',columns:3,children}];}
function retainRatio(p,b){const h=b.content.prompt.blocks.find(x=>x.type==='table');h.widths=[1,3];const tree=resolveArrangement(b).tree;function rows(n){if(n.id?.startsWith(b.content.id+':row:')&&n.direction==='row'&&n.children.length===2){n.children[0].weight=1;n.children[1].weight=3;}n.children?.forEach(rows);}rows(tree.root);p.settings.layoutOverrides.blockLayouts[b.id]={...p.settings.layoutOverrides.blockLayouts[b.id],arrangement:tree};b.sourceReview.customArrangement={reason:'One worked demonstration teaches three independent Your Turn tasks in each row. The outer paired grid allocates one quarter to the demonstration and three quarters to its native three-column response grid, preserving the meaningful 1:3 relationship and readable givens.'};}
export function repairOneToThree(source){return transform(source,'one-to-three-paired',p=>{
 if(p.id!==PROJECTS[0])return;
 let b=block(p,'p59-example-group');if(!b.sourceReview?.intentionalDepartures?.some(s=>String(s).includes('(one-to-three-paired)'))){const table=b.content.children[0],h=b.content.prompt.blocks[0];h.widths=[1,1];delete h.widthMm;for(const c of h.rows[0])delete c.colspan;retire(b,[table.id]);paired(p,b,table.children.flatMap(row=>rowParts(row,b)),h);}
 b=block(p,'p60-teaching');if(b.type==='rich-text'){const s=p.sections.find(s=>s.blocks.includes(b)),rows=Array.from({length:5},(_,i)=>block(p,`p60-r${i+1}-block`));if(rows.some(x=>!x||x.bankRef?.id))throw Error('Solve p60 rows changed');const h=b.content.blocks[0];h.widths=[1,1];delete h.widthMm;for(const c of h.rows[0])delete c.colspan;const parts=rows.flatMap(row=>rowParts(row.content,b));b.sourceReview??={};b.sourceReview.responses=rows.flatMap(row=>row.sourceReview?.responses??[]);b.sourceReview.workingSpaceEstimate={method:'solution-steps',estimates:rows.flatMap(row=>row.sourceReview?.workingSpaceEstimate?.estimates??[])};b.sourceRefs=[...(b.sourceRefs??[]),...rows.flatMap(row=>row.sourceRefs??[])];retire(b,rows.map(x=>x.id));for(const row of rows){clearArrangement(p,row,b);s.blocks.splice(s.blocks.indexOf(row),1);}b.content={id:'p60-paired-root',type:'group'};paired(p,b,parts,h);}
 for(const id of ['p59-example-group','p60-teaching']){const current=block(p,id);if(!current.sourceReview?.customArrangement?.reason?.includes('meaningful 1:3 relationship'))retainRatio(p,current);}
});}
await dryRunMain(import.meta.url,repairOneToThree,PROJECTS);
